import math

def calculate_T(r):
    """
    Calculates the maximum required T for the geometric sequence base r, 
    assuming the optimal configuration leads to T = |r^3 - r^-1|.
    This configuration uses the subset of exponents {1, 2, 3, 4} 
    and assigns values such that e/h = r^3 and g/f = r^-1.
    """
    if r <= 0:
        return None
    return abs(r**3 - (1/r))

# Test values for the geometric ratio r
r_values = [2, 3, 4, 5]
results = {}

for r in r_values:
    T = calculate_T(r)
    results[r] = T

print(f"Calculated T values for r={r_values}: {results}")

max_T = 0
for r, T in results.items():
    if T > max_T:
        max_T = T

print(f"Maximum T found in tests: {max_T}")
